#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    // [prefix x | middle | suffix y] -> [suffix | middle | prefix]
    vector<int> np;
    // suffix: p[n-y .. n-1]
    for (int i = n - y; i < n; i++) np.push_back(p[i]);
    // middle: p[x .. n-y-1]
    for (int i = x; i < n - y; i++) np.push_back(p[i]);
    // prefix: p[0 .. x-1]
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d", &n);
    vector<int> p(n);
    for (int i = 0; i < n; i++) scanf("%d", &p[i]);

    vector<pair<int,int>> ops;

    // Place elements 1, 2, ..., n into positions 0, 1, ..., n-1
    for (int placed = 0; placed <= n - 3; placed++) {
        // Find where element (placed+1) currently is
        int pos = -1;
        for (int i = placed; i < n; i++) {
            if (p[i] == placed + 1) { pos = i; break; }
        }
        if (pos == placed) continue; // already in place

        // Step 1: Move element to position n-1 (last position)
        if (pos != n - 1) {
            // We want to move element at position pos to position n-1
            // Use operation x = pos+1, y = n-1-pos
            // This puts suffix [pos+1..n-1] at front, prefix [0..pos] at end
            // Element at pos goes to end of array (last in prefix block)
            int x = pos + 1;
            int y = n - 1 - pos;
            if (x > 0 && y > 0 && x + y < n) {
                ops.push_back({x, y});
                apply_op(p, x, y);
            } else {
                // x + y = n means no middle. Need middle >= 1.
                // Use y = n - pos - 2 instead (one less suffix element)
                y = n - pos - 2;
                if (y > 0 && x > 0 && x + y < n) {
                    ops.push_back({x, y});
                    apply_op(p, x, y);
                }
            }
            // Re-find the element
            pos = -1;
            for (int i = 0; i < n; i++) {
                if (p[i] == placed + 1) { pos = i; break; }
            }
            if (pos == placed) continue;
            if (pos != n - 1) {
                // Try x=1, y=n-1-pos if valid
                int x2 = pos + 1, y2 = n - 1 - pos;
                if (x2 > 0 && y2 > 0 && x2 + y2 < n) {
                    ops.push_back({x2, y2});
                    apply_op(p, x2, y2);
                    pos = n - 1; // element should now be at end
                }
            }
        }

        // Step 2: Move element from position n-1 to position 'placed'
        // Operation (placed, 1): suffix=[p[n-1]], prefix=[p[0..placed-1]]
        // Result: [p[n-1]] + [p[placed..n-2]] + [p[0..placed-1]]
        // But we need placed > 0 for x > 0. If placed==0, use different approach.
        pos = -1;
        for (int i = 0; i < n; i++) if (p[i] == placed + 1) { pos = i; break; }
        if (pos == placed) continue;

        if (pos == n - 1 && placed + 1 + 1 <= n - 1) {
            // x = placed (if placed > 0), but we need x > 0
            // Actually we want element at n-1 to go to position placed
            // op(x, 1): puts p[n-1] at position 0, prefix p[0..x-1] at end
            // To get it to position 'placed', we need it at pos 0 first then shift?
            // Actually op(placed, 1) gives: [p[n-1], p[placed..n-2], p[0..placed-1]]
            // Element goes to position 0, not 'placed'. Hmm.
            // We need: after op, element at position 'placed'.
            // Use x = n - 1 - placed, y = 1: suffix=[p[n-1]], middle=[p[n-1-placed..n-2]], prefix=[p[0..n-2-placed]]
            // Result: [p[n-1], p[n-1-placed..n-2], p[0..n-2-placed]]
            // Element at position 0. Not helpful directly...
            // Just use op(1, 1) repeatedly? No, too many ops.
            // Use: first op(1,1) to bring to pos 0, then op to bring from 0 to placed
            if (placed == 0) {
                ops.push_back({1, 1});
                apply_op(p, 1, 1);
            } else {
                // op with y=1: [p[n-1], p[x..n-2], p[0..x-1]]. Element goes to pos 0.
                // Then op with x=1, y=n-placed: element from pos 0 goes to pos n-1 (end of prefix)
                // Hmm let me think differently.
                // op(n-1-placed, 1): result = [p[n-1]] + [p[n-1-placed..n-2]] + [p[0..n-2-placed]]
                // p[n-1] = placed+1 goes to position 0... not placed.
                // Direct: use x = n-1-placed, y = placed+1 ... but x+y = n, invalid if no middle
                // x = n-2-placed, y = placed+1, x+y = n-1 < n. Middle has 1 element.
                int xx = n - 2 - placed, yy = placed + 1;
                if (xx > 0 && yy > 0 && xx + yy < n) {
                    ops.push_back({xx, yy});
                    apply_op(p, xx, yy);
                }
            }
        }
    }

    printf("%d\n", (int)ops.size());
    for (auto& [x, y] : ops) printf("%d %d\n", x, y);
}
